import {Blankslate} from '@primer/react/experimental'
import {Button, Heading, Label, Link} from '@primer/react'
import {memo} from 'react'

import type {CodingGuidelineSummary, CodingGuidelinesPayload} from '../types'

export function CodingGuidelinesSection({codingGuidelines}: {codingGuidelines: CodingGuidelinesPayload}) {
  if (!codingGuidelines.featureEnabled) return null

  const {guidelines, newGuidelineUrl, totalCount, maxPerRepo} = codingGuidelines
  const reachedLimit = totalCount >= maxPerRepo
  const isEmpty = guidelines.length === 0

  return (
    <div className="tmp-mt-4">
      <div className="d-flex flex-items-end flex-justify-between tmp-mb-2">
        <div>
          <Heading as="h3" variant="small">
            Coding guidelines
          </Heading>
          <p className="mt-1 mb-0">
            Describe what patterns you&apos;d like Copilot to find and point out during code review.
          </p>
        </div>
        {!isEmpty && !reachedLimit && (
          <Button as="a" href={newGuidelineUrl} variant="primary" id="create-coding-guideline-button">
            Create guideline
          </Button>
        )}
      </div>

      {isEmpty ? (
        <Blankslate border>
          <Blankslate.Heading>No coding guidelines have been added</Blankslate.Heading>
          <Blankslate.Description>
            Copilot will review pull requests in this repository without custom instructions.
          </Blankslate.Description>
          {!reachedLimit && (
            <Blankslate.PrimaryAction href={newGuidelineUrl}>Create guideline</Blankslate.PrimaryAction>
          )}
        </Blankslate>
      ) : (
        <GuidelinesList guidelines={guidelines} />
      )}
    </div>
  )
}

function GuidelinesList({guidelines}: {guidelines: CodingGuidelineSummary[]}) {
  return (
    <div className="Box">
      {/* eslint-disable-next-line jsx-a11y/no-redundant-roles -- list-style:none strips semantics in Safari/VoiceOver */}
      <ul className="list-style-none" role="list">
        {guidelines.map(guideline => (
          <GuidelineRow key={guideline.id} guideline={guideline} />
        ))}
      </ul>
    </div>
  )
}

// eslint-disable-next-line @typescript-eslint/no-shadow -- named function expression intentionally shares the outer name
const GuidelineRow = memo(function GuidelineRow({guideline}: {guideline: CodingGuidelineSummary}) {
  return (
    <li className="Box-row d-flex flex-justify-between flex-items-center">
      <div className="d-flex flex-column">
        <Link href={guideline.editUrl} className="text-bold">
          {guideline.name}
        </Link>
        {guideline.description && <span className="color-fg-muted text-small">{guideline.description}</span>}
      </div>
      <Label variant={guideline.enabled ? 'success' : 'secondary'}>{guideline.enabled ? 'Enabled' : 'Disabled'}</Label>
    </li>
  )
})
