import {ControlGroup} from '@github-ui/control-group'
import {Heading, Link, Stack} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {useState, type ReactNode} from 'react'

import {useUpdateCodeReviewSetting} from '../hooks/useUpdateCodeReviewSetting'
import type {
  ApprovalSettingsPayload,
  BooleanSettingKey,
  QualifiedApprovalScopeWhenEnabled,
  QualifiedApprovalPayload,
} from '../types'
import {QualifiedApprovalFilePatternsForm} from './QualifiedApprovalFilePatternsForm'

type Props = {
  settingsEndpoint: string
  qualifiedApprovalEndpoint: string
  initialValue: ApprovalSettingsPayload
}

export function ApprovalsSection({settingsEndpoint, qualifiedApprovalEndpoint, initialValue}: Props) {
  const [autoApproveDelegatedEnabled, setAutoApproveDelegatedEnabled] = useState(
    initialValue.autoApprove.delegatedEnabled,
  )
  const [approvalGenerationEnabled, setApprovalGenerationEnabled] = useState(initialValue.approvalGenerationEnabled)
  const [qualifiedApprovalDelegatedEnabled, setQualifiedApprovalDelegatedEnabled] = useState(
    initialValue.qualifiedApproval.delegatedEnabled,
  )
  const [qualifiedApprovalEnabled, setQualifiedApprovalEnabled] = useState(initialValue.qualifiedApproval.enabled)
  const [qualifiedScopeWhenEnabled, setQualifiedScopeWhenEnabled] = useState<QualifiedApprovalScopeWhenEnabled>(
    initialValue.qualifiedApproval.scopeWhenEnabled,
  )
  const [qualifiedFilePatterns, setQualifiedFilePatterns] = useState(initialValue.qualifiedApproval.filePatterns)

  if (!initialValue.visible) return null

  const showQualifiedApproval = initialValue.qualifiedApproval.featureEnabled && approvalGenerationEnabled

  return (
    <div className="tmp-mt-4">
      <Heading as="h3" variant="small">
        Approvals
      </Heading>
      <Stack className="tmp-mt-3" gap="condensed">
        <ControlGroup>
          {initialValue.autoApprove.featureEnabled && (
            <ApprovalToggleSetting
              settingsEndpoint={settingsEndpoint}
              settingKey="repo_auto_approve_when_delegated"
              initialEnabled={autoApproveDelegatedEnabled}
              toggleRendered={initialValue.autoApprove.toggleRendered}
              labelId="ccr-auto-approve-when-delegated-label"
              descriptionId="ccr-auto-approve-when-delegated-description"
              title="Allow Copilot to approve pull requests"
              description={autoApproveDescription(initialValue)}
              onToggleSaved={next => {
                setAutoApproveDelegatedEnabled(next)
                setApprovalGenerationEnabled(next)
                setQualifiedApprovalEnabled(
                  next
                    ? qualifiedApprovalEnabledWhenApprovalGenerationEnabled(
                        initialValue.qualifiedApproval,
                        qualifiedApprovalDelegatedEnabled,
                      )
                    : false,
                )
              }}
            />
          )}

          {showQualifiedApproval && (
            <>
              <ApprovalToggleSetting
                settingsEndpoint={settingsEndpoint}
                settingKey="repo_qualified_approval_when_delegated"
                initialEnabled={qualifiedApprovalDelegatedEnabled}
                toggleRendered={initialValue.qualifiedApproval.toggleRendered}
                labelId="ccr-qualified-approval-when-delegated-label"
                descriptionId="ccr-qualified-approval-when-delegated-description"
                title="Allow Copilot approvals to count toward merge requirements"
                description={qualifiedApprovalDescription(
                  initialValue.qualifiedApproval,
                  initialValue.organizationSettingsUrl,
                )}
                onToggleSaved={next => {
                  setQualifiedApprovalDelegatedEnabled(next)
                  setQualifiedApprovalEnabled(next)
                }}
              />
              {initialValue.qualifiedApproval.formRendered && qualifiedApprovalEnabled && (
                <div className="border-top p-3">
                  <QualifiedApprovalFilePatternsForm
                    endpoint={qualifiedApprovalEndpoint}
                    initialScopeWhenEnabled={qualifiedScopeWhenEnabled}
                    initialFilePatterns={qualifiedFilePatterns}
                    maxFilePatternCount={initialValue.qualifiedApproval.maxFilePatternCount}
                    onSaved={({scopeWhenEnabled, filePatterns}) => {
                      setQualifiedScopeWhenEnabled(scopeWhenEnabled)
                      setQualifiedFilePatterns(filePatterns)
                    }}
                  />
                </div>
              )}
            </>
          )}
        </ControlGroup>
      </Stack>
    </div>
  )
}

type ApprovalToggleSettingProps = {
  settingsEndpoint: string
  settingKey: BooleanSettingKey
  initialEnabled: boolean
  toggleRendered: boolean
  labelId: string
  descriptionId: string
  title: ReactNode
  description?: ReactNode
  onToggleSaved: (enabled: boolean) => void
}

function ApprovalToggleSetting({
  settingsEndpoint,
  settingKey,
  initialEnabled,
  toggleRendered,
  labelId,
  descriptionId,
  title,
  description,
  onToggleSaved,
}: ApprovalToggleSettingProps) {
  const saveSetting = useUpdateCodeReviewSetting(settingsEndpoint)
  const [currentEnabled, setCurrentEnabled] = useState(initialEnabled)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const isSaving = saveSetting.isPending

  const handleToggle = async () => {
    if (isSaving) return

    const previous = currentEnabled
    const next = !currentEnabled
    setCurrentEnabled(next)
    onToggleSaved(next)
    setErrorMessage(null)

    try {
      await saveSetting.mutateAsync({setting: settingKey, value: next})
    } catch (error) {
      setCurrentEnabled(previous)
      onToggleSaved(previous)
      setErrorMessage(error instanceof Error ? error.message : 'An error occurred saving this setting.')
    }
  }

  return (
    <ControlGroup.Item>
      <ControlGroup.Title id={labelId}>{title}</ControlGroup.Title>
      <ControlGroup.Description id={descriptionId}>
        {description}
        <div role="status" aria-live="polite">
          {errorMessage && (
            <InlineMessage variant="critical" size="small" className={description !== undefined ? 'mt-1' : undefined}>
              {errorMessage}
            </InlineMessage>
          )}
        </div>
      </ControlGroup.Description>
      {toggleRendered && (
        <ControlGroup.ToggleSwitch
          aria-labelledby={labelId}
          aria-describedby={descriptionId}
          checked={currentEnabled}
          disabled={isSaving}
          onClick={() => {
            handleToggle()
          }}
        />
      )}
    </ControlGroup.Item>
  )
}

function autoApproveDescription(settings: ApprovalSettingsPayload): ReactNode {
  if (settings.autoApprove.forcedByRollout) return 'Enabled by runtime rollout.'
  if (settings.autoApprove.forcedByOrg) {
    return orgPolicyDescription('Enabled by organization policy.', settings.organizationSettingsUrl)
  }
  if (settings.autoApprove.disabledByOrg) {
    return orgPolicyDescription('Disabled by organization policy.', settings.organizationSettingsUrl)
  }
  return undefined
}

function qualifiedApprovalDescription(
  settings: QualifiedApprovalPayload,
  organizationSettingsUrl: string | null | undefined,
): ReactNode {
  if (settings.forcedByRollout) return 'Enabled by runtime rollout for all files.'
  if (settings.forcedByOrg) return orgPolicyDescription('Enabled by organization policy.', organizationSettingsUrl)
  if (settings.disabledByOrg) return orgPolicyDescription('Disabled by organization policy.', organizationSettingsUrl)
  return undefined
}

function orgPolicyDescription(message: string, organizationSettingsUrl: string | null | undefined): ReactNode {
  return (
    <>
      {message}
      {organizationSettingsUrl && (
        <>
          {' '}
          Manage this in{' '}
          <Link href={organizationSettingsUrl} inline>
            organization Copilot settings
          </Link>
          .
        </>
      )}
    </>
  )
}

function qualifiedApprovalEnabledWhenApprovalGenerationEnabled(
  settings: QualifiedApprovalPayload,
  delegatedEnabled: boolean,
): boolean {
  if (settings.forcedByRollout || settings.forcedByOrg) return true
  if (settings.disabledByOrg) return false
  return delegatedEnabled
}
